func contactsHaveQuick(data ContactsPageData) bool {
	return len(data.ManagerContacts)+len(data.EmergencyContacts)+len(data.BoardContacts) > 0
}
func contactsHaveAny(data ContactsPageData) bool {
	return contactsHaveQuick(data) || len(data.ManagedContacts)+len(data.ResidentContacts)+len(data.InactiveContacts) > 0
}
func contactsIssuesURL(canManage bool) string {
	if canManage {
		return "/app/anliegen/board"
	}
	return "/app/anliegen"
}
func contactRoleLabel(item view.ContactCardView) string {
	if item.Role == "Verwaltung" {
		return "Hausverwaltung"
	}
	return item.Role
}
func contactShowsDescription(item view.ManagedContactView) bool {
	return item.Description != "" && item.Description != item.Notes
}
func contactHasCapability(item view.ManagedContactView, capability string) bool {
	for _, current := range item.EnergyCapabilities {
		if current == capability {
			return true
		}
	}
	return false
}
func contactActiveValue(active bool) string {
	if active {
		return "true"
	}
	return "false"
}
func directoryStatus(optedIn bool) string {
	if optedIn {
		return "Ihr Kontakt ist für die Hausgemeinschaft sichtbar."
	}
	return "Ihr Kontakt ist derzeit nicht sichtbar."
}

